using FlexExtractor;
using Button=AntdUI.Button;
namespace FlexExtractor.UI;
public static class Ui {
 public static Color Ink=Color.FromArgb(20,30,48),Bg=Color.FromArgb(246,248,251),Blue=Color.FromArgb(22,119,255);
 public static void Shell(Form f,string title,Size size){f.Text=title;f.ClientSize=size;f.MinimumSize=size;f.StartPosition=FormStartPosition.CenterScreen;f.Font=new Font("Microsoft YaHei UI",10);f.BackColor=Bg;f.ForeColor=Ink;f.AutoScaleMode=AutoScaleMode.Dpi;var icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);if(icon!=null)f.Icon=icon;}
 public static Button Action(string text,string name,EventHandler click,bool primary=false){var b=new Button{Text=text,Name=name,Size=new Size(130,40),Type=primary?AntdUI.TTypeMini.Primary:AntdUI.TTypeMini.Default,Radius=6};b.Click+=click;return b;}
 public static Label Label(string text)=>new(){Text=text,AutoSize=true,Margin=new Padding(4,10,8,4)};
 public static void Error(IWin32Window owner,Exception ex)=>MessageBox.Show(owner,ex.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);
 public static TableLayoutPanel Fields()=>new(){Dock=DockStyle.Fill,ColumnCount=3,AutoScroll=true,Padding=new Padding(18),ColumnStyles={new(SizeType.Absolute,210),new(SizeType.Percent,100),new(SizeType.Absolute,130)}};
 public static void Row(TableLayoutPanel grid,string label,Control input,Control? button=null){var row=grid.RowCount++;grid.RowStyles.Add(new(SizeType.Absolute,48));grid.Controls.Add(Label(label),0,row);input.Dock=DockStyle.Fill;input.Margin=new Padding(4,6,8,6);grid.Controls.Add(input,1,row);if(button!=null)grid.Controls.Add(button,2,row);}
 public static void Browse(TextBox box){using var d=new FolderBrowserDialog{Description="选择目录"};if(d.ShowDialog()==DialogResult.OK)box.Text=d.SelectedPath;}
}
public sealed class ConfigEditor:Form {
 public Config Edited {get;private set;}
 readonly Dictionary<string,Control> fields=new();readonly ListBox dispense=new(){Name="DispenseItems",Dock=DockStyle.Fill},bind=new(){Name="BindItems",Dock=DockStyle.Fill};readonly TabControl tabs=new(){Dock=DockStyle.Fill};
 public ConfigEditor(Config source){Edited=Config.Parse(System.Text.Json.JsonSerializer.Serialize(source,Config.Json));Ui.Shell(this,"提取配置",new Size(1060,760));var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};root.RowStyles.Add(new(SizeType.Percent,100));root.RowStyles.Add(new(SizeType.Absolute,64));root.Controls.Add(tabs);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(14,8,14,8)};buttons.Controls.Add(Ui.Action("保存配置","SaveConfig",(_,_)=>{try{Collect();Edited.Validate();DialogResult=DialogResult.OK;}catch(Exception ex)when(ex is InvalidDataException or ArgumentException){Ui.Error(this,ex);}},true));buttons.Controls.Add(Ui.Action("取消","CancelConfig",(_,_)=>DialogResult=DialogResult.Cancel));buttons.Controls.Add(Ui.Action("导入旧版…","ImportLegacy",(_,_)=>ImportLegacy()));root.Controls.Add(buttons,0,1);Controls.Add(root);Build();}
 void Build(){tabs.TabPages.Clear();fields.Clear();var common=new TabPage("目录与站位");var grid=Ui.Fields();common.Controls.Add(grid);tabs.TabPages.Add(common);var watch=new TextBox{Name="WatchRoot",Text=Edited.WatchRoot};fields.Add("WatchRoot",watch);Ui.Row(grid,"报文根目录",watch,Ui.Action("选择…","BrowseWatch",(_,_)=>Ui.Browse(watch)));
  void Stations(string title,ListBox list,List<Station> items,bool isBind){var row=grid.RowCount++;grid.RowStyles.Add(new(SizeType.Absolute,210));grid.Controls.Add(Ui.Label(title),0,row);list.Items.Clear();list.Items.AddRange(items.Cast<object>().ToArray());grid.Controls.Add(list,1,row);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown};actions.Controls.Add(Ui.Action("新增","Add"+title,(_,_)=>EditStation(list,items,isBind,false)));actions.Controls.Add(Ui.Action("编辑","Edit"+title,(_,_)=>EditStation(list,items,isBind,true)));actions.Controls.Add(Ui.Action("删除","Delete"+title,(_,_)=>{if(list.SelectedIndex>=0){items.RemoveAt(list.SelectedIndex);list.Items.RemoveAt(list.SelectedIndex);}}));grid.Controls.Add(actions,2,row);list.DoubleClick+=(_,_)=>EditStation(list,items,isBind,true);}
  Stations("点胶站",dispense,Edited.DispenseItems,false);Stations("组装站",bind,Edited.BindItems,true);
  var advanced=new TabPage("时序与资源上限");var settings=Ui.Fields();advanced.Controls.Add(settings);tabs.TabPages.Add(advanced);
  void Number(string property,string label,long min,long max){var value=Convert.ToDecimal(typeof(Config).GetProperty(property)!.GetValue(Edited));var n=new NumericUpDown{Name=property,Minimum=min,Maximum=max,Value=Math.Clamp(value,min,max)};fields.Add(property,n);Ui.Row(settings,label,n);}
  Number("PollIntervalSec","轮询间隔（秒）",1,60);Number("LookbackDays","日期回溯（天）",1,14);Number("KeepDays","保留时长（天）",1,14);var only=new CheckBox{Name="OnlyNewAfterStart",Text="只提取首次会话之后的新报文",Checked=Edited.OnlyNewAfterStart};fields.Add("OnlyNewAfterStart",only);Ui.Row(settings,"启动范围",only);Number("NewFileGraceSec","新报文宽限（秒）",0,30);Number("MinFileBytes","最小文件（字节）",1,16777216);Number("SizeStableChecks","稳定检查（次）",0,8);Number("SizeStableIntervalMs","稳定间隔（毫秒）",0,2000);Number("MaxLogLines","界面日志（行）",50,2000);Number("WorkerTimeoutSec","工作进程超时（秒）",2,600);Number("MaxFileBytes","最大报文（字节）",16,134217728);Number("MaxFilesPerPass","每批报文上限（份）",1,10000);
 }
 void Collect(){Edited.WatchRoot=((TextBox)fields["WatchRoot"]).Text.Trim();foreach(var (name,control) in fields){if(control is NumericUpDown n){var p=typeof(Config).GetProperty(name)!;p.SetValue(Edited,Convert.ChangeType(n.Value,p.PropertyType));}}Edited.OnlyNewAfterStart=((CheckBox)fields["OnlyNewAfterStart"]).Checked;}
 void EditStation(ListBox list,List<Station> items,bool isBind,bool edit){if(edit&&list.SelectedIndex<0)return;Collect();var original=edit?items[list.SelectedIndex]:new Station{Token=isBind?"0061":"0031",StationName=isBind?"组装61":"点胶31"};using var dialog=new StationEditor(Edited,original);if(dialog.ShowDialog(this)!=DialogResult.OK)return;if(edit)items[list.SelectedIndex]=dialog.Edited;else items.Add(dialog.Edited);list.Items.Clear();list.Items.AddRange(items.Cast<object>().ToArray());}
 void ImportLegacy(){using var d=new OpenFileDialog{Filter="旧版JSON配置|*.json",Title="显式导入1.3.2配置（源文件不会修改）"};if(d.ShowDialog(this)!=DialogResult.OK)return;try{var imported=Config.Parse(Durable.Read(d.FileName,65536),true,Path.GetDirectoryName(d.FileName));imported.Validate();Edited=imported;Build();MessageBox.Show(this,"已导入草稿；检查目录后点保存。原配置未修改。","导入");}catch(Exception ex)when(ex is IOException or InvalidDataException or System.Text.Json.JsonException or ArgumentException){Ui.Error(this,ex);}}
}
